/// 两条排序接口的 APP 签名材料。
///
/// 它们的 csrf **被签名覆盖**，所以 csrf 的注入点前移到了请求构造处
/// （见 `bili_api::fav` 的模块文档）。这里把签名材料单独递过去。
class FavSignature {
  final String appkey;
  final String appsec;

  /// 签名用的 Unix 秒，由调用方注入以便快照固定。
  final PlatformInt64 ts;

  const FavSignature({
    required this.appkey,
    required this.appsec,
    required this.ts,
  });

  @override
  int get hashCode => appkey.hashCode ^ appsec.hashCode ^ ts.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FavSignature &&
          runtimeType == other.runtimeType &&
          appkey == other.appkey &&
          appsec == other.appsec &&
          ts == other.ts;
}

